import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Repair Station","description":"","frontmatter":{},"headers":[],"relativePath":"repair-station/index.md","filePath":"repair-station/index.md"}'),n={name:"repair-station/index.md"};function r(o,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="repair-station" tabindex="-1">Repair Station <a class="header-anchor" href="#repair-station" aria-label="Permalink to &quot;Repair Station&quot;">​</a></h1><p>Drive onto a repair station, pick a service, and the vehicle is repaired on the spot: engine, body and tyres, with sound and sparks. The price follows the damage, so a scratched car pays less than a wreck. Stations are placed in game and every setting is edited in game.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Three services out of the box</strong>: quick fix (engine), body work (body and tyres), full repair. Name, price, duration and repaired parts are yours to change. See <a href="/repair-station/settings">Settings</a>.</li><li><strong>Price by damage</strong>: the price scales with the damage of the parts repaired, down to a minimum percentage. Undamaged vehicles are refused.</li><li><strong>In-game station editor</strong>: create a station where you stand, move the stopping area and an optional prop with the keyboard, save. See <a href="/repair-station/stations">Stations</a>.</li><li><strong>Mechanics first</strong>: stations close while enough mechanics are on duty, so players call them instead.</li><li><strong>Fair and safe</strong>: one vehicle per station, driver and speed checks, payments validated on the server. A cancelled repair is refunded to the account that was charged.</li><li><strong>Job discounts</strong>, a price percentage per station, and payment from cash, bank, or cash then bank.</li><li><strong>Everything in <code>/nay</code></strong>: services, prices, stations, mechanic jobs, blips with a visual icon and colour picker.</li><li><strong>HTTP API and webhooks</strong>: repair history, statistics and stations for your website or bot, a Discord message for every repair. See <a href="/repair-station/api">API and webhooks</a>.</li><li><strong>Extensible</strong>: a second resource can change prices, close stations and take part in every repair. See <a href="/repair-station/api#extensions">Extensions</a>.</li><li><strong>Six languages</strong>: English, French, Spanish, Portuguese, Polish, German.</li></ul><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detected automatically.</li><li>Dependencies: oxmysql and <code>nay_lib</code> (included with your purchase).</li></ul><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span></code></pre></div><p>Full steps on the <a href="/getting-started">Getting started</a> page. Then give yourself <code>nay_repair.config</code> (or <code>nay.admin</code>) and open <code>/nay</code>. Three stations are ready out of the box: Hayes Autos, Sandy Shores and Paleto Bay.</p>`,9)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
